/**
 * Lightweight Standalone Markdown Parser for MarkItDown Studio v0.2.0
 * Converts Markdown headings, bold/italics, lists, tables, code blocks, blockquotes, links, images, and horizontal rules into clean HTML.
 */
window.marked = {
    parse: function(markdown) {
        if (!markdown) return '';
        
        // Normalize line endings
        let src = markdown.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
        
        // Escape HTML tags to prevent XSS while preserving markdown
        const escapeHtml = (text) => {
            return text
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        };

        // Extract and protect fenced code blocks
        const codeBlocks = [];
        src = src.replace(/```([a-zA-Z0-9_\-+#]*)\n([\s\S]*?)```/g, function(match, lang, code) {
            const index = codeBlocks.length;
            const cleanLang = lang.trim() || 'text';
            const escapedCode = escapeHtml(code.trim());
            codeBlocks.push(`<div class="code-block-wrapper"><div class="code-header"><span class="code-lang">${cleanLang}</span><button class="btn-copy-code" onclick="navigator.clipboard.writeText(decodeURIComponent('${encodeURIComponent(code.trim())}'));showToast('Código copiado!', 'success')">Copiar</button></div><pre><code class="language-${cleanLang}">${escapedCode}</code></pre></div>`);
            return `@@@CODEBLOCK_${index}@@@`;
        });

        // Extract inline code
        const inlineCodes = [];
        src = src.replace(/`([^`\n]+)`/g, function(match, code) {
            const index = inlineCodes.length;
            inlineCodes.push(`<code>${escapeHtml(code)}</code>`);
            return `@@@INLINECODE_${index}@@@`;
        });

        // Split into lines for block parsing
        let lines = src.split('\n');
        let htmlLines = [];
        let inList = false;
        let listType = null;
        let inBlockquote = false;
        let tableBuffer = [];

        const flushTable = () => {
            if (tableBuffer.length === 0) return;
            let tableHtml = '<div class="table-responsive"><table class="md-table">';
            
            // First line is header
            let headerCells = tableBuffer[0].split('|').map(c => c.trim()).filter((c, idx, arr) => idx > 0 && idx < arr.length - 1 || (arr.length <= 2 && c.length > 0));
            if (headerCells.length === 0) {
                headerCells = tableBuffer[0].split('|').map(c => c.trim()).filter(c => c);
            }
            
            tableHtml += '<thead><tr>';
            headerCells.forEach(cell => {
                tableHtml += `<th>${parseInline(cell)}</th>`;
            });
            tableHtml += '</tr></thead>';

            // Check if there are body rows (skip row 1 if it is separator ---|---)
            let bodyRows = tableBuffer.slice(1);
            if (bodyRows.length > 0 && /^[|\s:\-]+$/.test(bodyRows[0])) {
                bodyRows = bodyRows.slice(1);
            }

            if (bodyRows.length > 0) {
                tableHtml += '<tbody>';
                bodyRows.forEach(row => {
                    let cells = row.split('|').map(c => c.trim()).filter((c, idx, arr) => idx > 0 && idx < arr.length - 1 || (arr.length <= 2 && c.length > 0));
                    if (cells.length === 0) {
                        cells = row.split('|').map(c => c.trim()).filter(c => c);
                    }
                    tableHtml += '<tr>';
                    cells.forEach(cell => {
                        tableHtml += `<td>${parseInline(cell)}</td>`;
                    });
                    tableHtml += '</tr>';
                });
                tableHtml += '</tbody>';
            }

            tableHtml += '</table></div>';
            htmlLines.push(tableHtml);
            tableBuffer = [];
        };

        const flushList = () => {
            if (inList) {
                htmlLines.push(listType === 'ol' ? '</ol>' : '</ul>');
                inList = false;
                listType = null;
            }
        };

        const flushBlockquote = () => {
            if (inBlockquote) {
                htmlLines.push('</blockquote>');
                inBlockquote = false;
            }
        };

        function parseInline(text) {
            if (!text) return '';
            
            // Images: ![alt](url)
            text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" class="md-image" />');
            
            // Links: [text](url)
            text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" class="md-link">$1</a>');
            
            // Bold + Italic: ***text*** or ___text___
            text = text.replace(/(\*\*\*|___)(.*?)\1/g, '<strong><em>$2</em></strong>');
            
            // Bold: **text** or __text__
            text = text.replace(/(\*\*|__)(.*?)\1/g, '<strong>$2</strong>');
            
            // Italic: *text* or _text_
            text = text.replace(/(\*|_)(.*?)\1/g, '<em>$2</em>');
            
            // Strikethrough: ~~text~~
            text = text.replace(/~~(.*?)~~/g, '<del>$1</del>');

            return text;
        }

        for (let i = 0; i < lines.length; i++) {
            let line = lines[i];
            let trimmed = line.trim();

            // Check if table row
            if (trimmed.startsWith('|') && trimmed.endsWith('|') && trimmed.length > 1) {
                flushList();
                flushBlockquote();
                tableBuffer.push(trimmed);
                continue;
            } else if (tableBuffer.length > 0) {
                flushTable();
            }

            // Empty line
            if (trimmed === '') {
                flushList();
                flushBlockquote();
                continue;
            }

            // Headers (# to ######)
            let headerMatch = trimmed.match(/^(#{1,6})\s+(.*)$/);
            if (headerMatch) {
                flushList();
                flushBlockquote();
                let level = headerMatch[1].length;
                let title = parseInline(headerMatch[2]);
                htmlLines.push(`<h${level} class="md-h${level}">${title}</h${level}>`);
                continue;
            }

            // Horizontal Rule (---, ***, ___)
            if (/^(\-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
                flushList();
                flushBlockquote();
                htmlLines.push('<hr class="md-hr" />');
                continue;
            }

            // Blockquote (> text)
            if (trimmed.startsWith('>')) {
                flushList();
                if (!inBlockquote) {
                    htmlLines.push('<blockquote class="md-blockquote">');
                    inBlockquote = true;
                }
                let quoteText = parseInline(trimmed.replace(/^>\s?/, ''));
                htmlLines.push(`<p>${quoteText}</p>`);
                continue;
            } else if (inBlockquote) {
                flushBlockquote();
            }

            // Unordered List (*, -, +)
            let ulMatch = line.match(/^(\s*)([*+-])\s+(.*)$/);
            if (ulMatch) {
                flushBlockquote();
                if (!inList || listType !== 'ul') {
                    flushList();
                    htmlLines.push('<ul class="md-ul">');
                    inList = true;
                    listType = 'ul';
                }
                let content = ulMatch[3];
                // Checkbox items [ ] or [x]
                if (content.startsWith('[ ] ')) {
                    htmlLines.push(`<li class="task-item"><input type="checkbox" disabled /> ${parseInline(content.substring(4))}</li>`);
                } else if (content.startsWith('[x] ') || content.startsWith('[X] ')) {
                    htmlLines.push(`<li class="task-item"><input type="checkbox" checked disabled /> ${parseInline(content.substring(4))}</li>`);
                } else {
                    htmlLines.push(`<li>${parseInline(content)}</li>`);
                }
                continue;
            }

            // Ordered List (1., 2., etc.)
            let olMatch = line.match(/^(\s*)(\d+)\.\s+(.*)$/);
            if (olMatch) {
                flushBlockquote();
                if (!inList || listType !== 'ol') {
                    flushList();
                    htmlLines.push('<ol class="md-ol">');
                    inList = true;
                    listType = 'ol';
                }
                htmlLines.push(`<li>${parseInline(olMatch[3])}</li>`);
                continue;
            }

            // Regular paragraph or placeholder
            flushList();
            flushBlockquote();
            
            if (trimmed.startsWith('@@@CODEBLOCK_')) {
                htmlLines.push(trimmed);
            } else {
                htmlLines.push(`<p class="md-p">${parseInline(line)}</p>`);
            }
        }

        flushTable();
        flushList();
        flushBlockquote();

        let resultHtml = htmlLines.join('\n');

        // Restore code blocks
        codeBlocks.forEach((codeHtml, idx) => {
            resultHtml = resultHtml.replace(new RegExp(`@@@CODEBLOCK_${idx}@@@`, 'g'), codeHtml);
            resultHtml = resultHtml.replace(new RegExp(`<p class="md-p">@@@CODEBLOCK_${idx}@@@</p>`, 'g'), codeHtml);
        });

        // Restore inline codes
        inlineCodes.forEach((inlineHtml, idx) => {
            resultHtml = resultHtml.replace(new RegExp(`@@@INLINECODE_${idx}@@@`, 'g'), inlineHtml);
        });

        return resultHtml;
    }
};
